begin;
\if :{?fixture_owner}
\else
select current_user as fixture_owner \gset
\endif
set local role :"fixture_owner";
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
\ir ../fixtures.sql
select no_plan();
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000008","role":"authenticated"}',true);
set local role authenticated;
select is(current_user::text,'authenticated','ordinary group administrator');
select is(auth.uid(),'20000000-0000-4000-8000-000000000008'::uuid,'verified identity');
select lives_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000920","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=MONTHLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"monthly","monthlyMode":"day","monthDay":31},"occurrences":[{"original_local_date":"2099-01-31","required_arrival_at":"2099-01-31T09:00Z"},{"original_local_date":"2099-03-31","required_arrival_at":"2099-03-31T09:00Z"}]}')$rpc$,'monthly 31 skips missing dates');
select lives_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000921","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=MONTHLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"monthly","monthlyMode":"weekday","ordinal":-1,"weekday":"MO"},"occurrences":[{"original_local_date":"2099-01-26","required_arrival_at":"2099-01-26T09:00Z"},{"original_local_date":"2099-02-23","required_arrival_at":"2099-02-23T09:00Z"}]}')$rpc$,'last monthly weekday');
select lives_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000922","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=MONTHLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"monthly","monthlyMode":"weekday","ordinal":5,"weekday":"MO"},"occurrences":[{"original_local_date":"2099-03-30","required_arrival_at":"2099-03-30T09:00Z"}]}')$rpc$,'fifth monthly weekday');
select throws_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000923","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=MONTHLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"monthly","monthlyMode":"day","monthDay":31},"occurrences":[{"original_local_date":"2099-02-28","required_arrival_at":"2099-02-28T09:00Z"}]}')$rpc$,'22023',null,'month end substitution denied');
select throws_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000924","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=WEEKLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"weekly","weekdays":["MO"]},"occurrences":[{"original_local_date":"2099-01-06","required_arrival_at":"2099-01-06T09:00Z"}]}')$rpc$,'22023',null,'wrong weekly weekday denied');
select lives_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000925","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=WEEKLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"weekly","weekdays":["MO"]},"occurrences":[{"original_local_date":"2099-01-05","required_arrival_at":"2099-01-05T09:00Z"},{"original_local_date":"2099-01-12","required_arrival_at":"2099-01-12T09:00Z"}]}')$rpc$,'selected weekly weekdays accepted');
select throws_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000926","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=MONTHLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"monthly","monthlyMode":"weekday","ordinal":5,"weekday":"MO"},"occurrences":[{"original_local_date":"2099-02-23","required_arrival_at":"2099-02-23T09:00Z"}]}')$rpc$,'22023',null,'fourth is not fifth weekday');
select throws_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000927","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=MONTHLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"monthly","monthlyMode":"weekday","ordinal":0,"weekday":"MO"},"occurrences":[{"original_local_date":"2099-01-05","required_arrival_at":"2099-01-05T09:00Z"}]}')$rpc$,'22023',null,'ordinal zero denied');
select throws_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000928","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=WEEKLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"weekly","weekdays":["XX"]},"occurrences":[{"original_local_date":"2099-01-05","required_arrival_at":"2099-01-05T09:00Z"}]}')$rpc$,'22023',null,'unsupported weekday denied');
select throws_ok($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000929","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=DAILY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-01","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"daily"},"occurrences":[{"original_local_date":"2099-01-01","required_arrival_at":"2099-01-01T09:00Z"},{"original_local_date":"2099-01-01","required_arrival_at":"2099-01-01T09:00Z"}]}')$rpc$,'22023',null,'duplicate occurrence dates denied');
select is((select count(*)::integer from public.event_series where request_id in ('20000000-0000-4000-8000-000000000923','20000000-0000-4000-8000-000000000924','20000000-0000-4000-8000-000000000926','20000000-0000-4000-8000-000000000927','20000000-0000-4000-8000-000000000928','20000000-0000-4000-8000-000000000929')),0,'rejected batches leave no templates');
select id as replacement_id from public.events where event_series_id in(select id from public.event_series where request_id='20000000-0000-4000-8000-000000000920') order by original_local_date limit 1 \gset
select lives_ok(format($rpc$select public.series_workflow('{"groupId":"20000000-0000-4000-8000-000000000301","requestId":"20000000-0000-4000-8000-000000000930","name":"Synthetic series","locationId":"20000000-0000-4000-8000-000000000501","rule":"FREQ=MONTHLY;INTERVAL=1","spec":{"interval":1,"startDate":"2099-01-31","endDate":"2099-04-30","timezone":"UTC","arrivalTime":"09:00","frequency":"monthly","monthlyMode":"day","monthDay":31},"occurrences":[{"original_local_date":"2099-01-31","required_arrival_at":"2099-01-31T09:00Z"},{"original_local_date":"2099-03-31","required_arrival_at":"2099-03-31T09:00Z"}],"seriesRevision":1,"replaceEventId":"%s"}')$rpc$,:'replacement_id'),'future replacement is atomic');
select is((select count(*)::integer from public.events where event_series_id in(select id from public.event_series where request_id='20000000-0000-4000-8000-000000000920') and status='cancelled'),2,'superseded occurrences preserved as cancelled');
select is((select count(*)::integer from public.event_participation where event_id in(select id from public.events where event_series_id in(select id from public.event_series where request_id='20000000-0000-4000-8000-000000000930'))),0,'successor events have unconfigured attendance');
select * from finish();
rollback;
